class Solution:
    def numOfSubarrays(self, arr: List[int], k: int, threshold: int) -> int:
        n = len(arr)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + arr[i]
        target = k * threshold
        return sum(1 for i in range(n - k + 1) if prefix[i + k] - prefix[i] >= target)

