class Solution {
public:
    int numOfSubarrays(vector<int>& arr, int k, int threshold) {
        int n = arr.size();
        vector<long long> prefix(n + 1, 0);
        for (int i = 0; i < n; ++i) prefix[i + 1] = prefix[i] + arr[i];
        long long target = (long long)k * threshold;
        int count = 0;
        for (int i = 0; i + k <= n; ++i)
            if (prefix[i + k] - prefix[i] >= target) count++;
        return count;
    }
};

